<section class="users-table-card"><header><div><h2>Usuarios registrados</h2><span><?=count($users)?> resultados</span></div></header><?php if(!$users):?><div class="users-empty"><i class="fa-solid fa-users"></i><strong>No se encontraron usuarios</strong><p>Cambia los filtros o registra una nueva cuenta.</p></div><?php else:?><div class="users-table-wrap"><table><thead><tr><th>Usuario</th><th>Rol</th><th>Información académica</th><th>Estado</th><th>Último acceso</th><th><span class="sr-only">Acciones</span></th></tr></thead><tbody><?php foreach($users as $user):$roleLabels=['student'=>'Estudiante','teacher'=>'Docente','administrator'=>'Administrador'];?><tr><td><div class="user-cell"><span><?=e(mb_strtoupper(mb_substr($user['full_name'],0,1,'UTF-8'),'UTF-8'))?></span><div><strong><?=e($user['full_name'])?></strong><small><?=e($user['email'])?></small></div></div></td><td><span class="role-chip <?=e($user['role_code'])?>"><?=e($roleLabels[$user['role_code']]??$user['role_code'])?></span></td><td><div class="academic-cell"><?php if($user['role_code']==='student'):?><strong><?=e($user['career_name']??'Sin carrera')?></strong><small><?= (int)$user['semester']?>.º semestre · <?=e($user['institutional_code'])?></small><?php elseif($user['role_code']==='teacher'):?><strong><?=e($user['academic_title']?:'Docente')?></strong><small><?=e($user['institutional_code'])?><?=!empty($user['can_tutor'])?' · Disponible como tutor':''?></small><?php else:?><strong>Administración del sistema</strong><?php endif;?></div></td><td><span class="status-chip <?=e($user['status'])?>"><?=e(['active'=>'Activo','inactive'=>'Inactivo','blocked'=>'Bloqueado'][$user['status']]??$user['status'])?></span><?php if($user['must_change_password']):?><small class="temporary-label">Contraseña temporal</small><?php endif;?></td><td><small><?= $user['last_login_at']?e(date('d/m/Y H:i',strtotime($user['last_login_at']))):'Nunca'?></small></td><td><button class="user-actions-button" type="button" aria-label="Acciones de <?=e($user['full_name'])?>"><i class="fa-solid fa-ellipsis"></i></button><div class="user-actions" hidden><button type="button" data-action="edit">Editar</button><button type="button" data-action="password">Restablecer contraseña</button><?php if($user['status']!=='active'):?><button type="button" data-action="status" data-status="active">Activar acceso</button><?php endif;?><?php if($user['status']!=='blocked'):?><button type="button" data-action="status" data-status="blocked" class="danger">Bloquear acceso</button><?php endif;?></div><script type="application/json" class="user-data"><?=json_encode($user,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE)?></script></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>

